import re

def compare_versions(a, b):
    def parse(version):
        if not isinstance(version, str):
            raise ValueError("version must be a string")
        m = re.fullmatch(
            r'(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)'
            r'(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'
            r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?',
            version
        )
        if not m:
            raise ValueError("invalid version: %r" % (version,))
        major, minor, patch, prerelease, _build = m.groups()
        pre = prerelease.split('.') if prerelease is not None else None
        return (int(major), int(minor), int(patch), pre)

    def cmp_ident(x, y):
        x_num = x.isdigit()
        y_num = y.isdigit()
        if x_num and y_num:
            xi, yi = int(x), int(y)
            return (xi > yi) - (xi < yi)
        if x_num:
            return -1
        if y_num:
            return 1
        return (x > y) - (x < y)

    pa = parse(a)
    pb = parse(b)

    for i in range(3):
        if pa[i] != pb[i]:
            return 1 if pa[i] > pb[i] else -1

    pre_a, pre_b = pa[3], pb[3]
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    for x, y in zip(pre_a, pre_b):
        c = cmp_ident(x, y)
        if c != 0:
            return c

    if len(pre_a) != len(pre_b):
        return -1 if len(pre_a) < len(pre_b) else 1
    return 0
