def wildcard_match(pattern, text):
    if not isinstance(pattern, str) or not isinstance(text, str):
        raise ValueError("pattern and text must be str")

    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("dangling escape")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '*':
            if i + 1 < n and pattern[i + 1] == '*':
                tokens.append(('dstar', None))
                i += 2
            else:
                tokens.append(('star', None))
                i += 1
        elif c == '?':
            tokens.append(('q', None))
            i += 1
        else:
            tokens.append(('lit', c))
            i += 1

    m = len(tokens)
    tlen = len(text)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(ti, pi):
        if pi == m:
            return ti == tlen
        kind, val = tokens[pi]
        if kind == 'lit':
            if ti < tlen and text[ti] == val:
                return match(ti + 1, pi + 1)
            return False
        if kind == 'q':
            if ti < tlen and text[ti] != '/':
                return match(ti + 1, pi + 1)
            return False
        if kind == 'star':
            if match(ti, pi + 1):
                return True
            if ti < tlen and text[ti] != '/':
                return match(ti + 1, pi)
            return False
        if kind == 'dstar':
            if match(ti, pi + 1):
                return True
            if ti < tlen:
                return match(ti + 1, pi)
            return False
        return False

    return match(0, 0)
