    if not values:
        return []
    nums = sorted(set(values))
    result = []
    start = prev = nums[0]
    for n in nums[1:]:
        if n == prev + 1:
            prev = n
        else:
            result.append((start, prev))
            start = prev = n
    result.append((start, prev))
    return result
